def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    p = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for el, x in s.get('composition', {}).items():
        r = p.get(el, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and r > 0:
            total += x * r * r * r
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    p = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for el, x in s.get('composition', {}).items():
        z = p.get(el, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and z >= 0:
            total += x * z
            weight += x
    if weight <= 0:
        return 0.0
    return float(total / (weight * v))

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    w = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf for i in range(n)]
    for e in s.get('neighbors', ()):
        i = e.get('i', -1)
        j = e.get('j', -1)
        d = e.get('distance_A')
        if 0 <= i < n and 0 <= j < n and w[j] > 0 and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    weight = sum(w[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    return float(sum(w[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    w = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf for i in range(n)]
    for e in s.get('neighbors', ()):
        i = e.get('i', -1)
        j = e.get('j', -1)
        d = e.get('distance_A')
        if 0 <= i < n and 0 <= j < n and w[j] > 0 and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    weight = sum(w[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    mean = sum(w[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / weight
    if mean <= 0:
        return 0.0
    var = sum(w[i] * (nearest[i] - mean) ** 2 for i in range(n) if math.isfinite(nearest[i])) / weight
    return float(math.sqrt(max(0.0, var)) / mean)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    w = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    weight = sum(w)
    if weight <= 0:
        return 0.0
    nearest = [math.inf for i in range(n)]
    edges = s.get('neighbors', ())
    for e in edges:
        i = e.get('i', -1)
        j = e.get('j', -1)
        d = e.get('distance_A')
        if 0 <= i < n and 0 <= j < n and w[j] > 0 and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    count = [0.0 for i in range(n)]
    for e in edges:
        i = e.get('i', -1)
        j = e.get('j', -1)
        d = e.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.25 * nearest[i]:
            count[i] += w[j]
    return float(sum(w[i] * count[i] for i in range(n)) / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    props = s.get('element_properties', {})
    en = [props.get(t.get('element'), {}).get('eneg') for t in sites]
    w = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    weight = sum(w)
    if weight <= 0:
        return 0.0
    nearest = [math.inf for i in range(n)]
    edges = s.get('neighbors', ())
    for e in edges:
        i = e.get('i', -1)
        j = e.get('j', -1)
        d = e.get('distance_A')
        if 0 <= i < n and 0 <= j < n and w[j] > 0 and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    total = 0.0
    for e in edges:
        i = e.get('i', -1)
        j = e.get('j', -1)
        d = e.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.25 * nearest[i]:
            if en[i] is not None and en[j] is not None:
                total += w[i] * w[j] * (en[i] - en[j]) ** 2 / d
    return float(0.5 * total / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    props = s.get('element_properties', {})
    chi = [None for i in range(n)]
    hardness = [None for i in range(n)]
    for i in range(n):
        p = props.get(sites[i].get('element'), {})
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is not None and affinity is not None and ion > affinity:
            chi[i] = 0.5 * (ion + affinity)
            hardness[i] = 0.5 * (ion - affinity)
    w = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    weight = sum(w)
    if weight <= 0:
        return 0.0
    nearest = [math.inf for i in range(n)]
    edges = s.get('neighbors', ())
    for e in edges:
        i = e.get('i', -1)
        j = e.get('j', -1)
        d = e.get('distance_A')
        if 0 <= i < n and 0 <= j < n and w[j] > 0 and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    total = 0.0
    for e in edges:
        i = e.get('i', -1)
        j = e.get('j', -1)
        d = e.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.25 * nearest[i]:
            if chi[i] is not None and chi[j] is not None:
                h = hardness[i] + hardness[j]
                if h > 0:
                    total += w[i] * w[j] * (chi[i] - chi[j]) ** 2 / (2.0 * h)
    return float(0.5 * total / weight)
